export function Interactive(): JSX.Element {
  const [groupValue, setGroupValue] = useState<string | number>('A')
  const [buttonValue, setButtonValue] = useState<string | number>(1)

  const onChangeButton = (event: ChangeEvent<HTMLInputElement>) => {
    setButtonValue(event.target.value)
  }

  const onChangeGroup = (event: { target: { value: string | number } }) => {
    setGroupValue(event.target.value)
  }

  return (
    <div>
      <div className="flex flex-row m-6 justify-evenly">
        <Radio.Group
          color="primary"
          defaultValue={groupValue}
          direction="col"
          onChange={onChangeGroup}
          size="medium"
        >
          <Radio.Label>Group onChange</Radio.Label>
          <Radio.Input value={'A'}>A</Radio.Input>
          <Radio.Input value={'B'}>B</Radio.Input>
          <Radio.Input value={'C'}>C</Radio.Input>
        </Radio.Group>
        {groupValue} is the selected value
      </div>

      <div className="flex flex-row m-6 justify-evenly">
        <Radio.Group
          color="primary"
          defaultValue={buttonValue}
          direction="col"
          size="medium"
        >
          <Radio.Label>Button onChange</Radio.Label>
          <Radio.Input onChange={onChangeButton} value={1}>
            1
          </Radio.Input>
          <Radio.Input onChange={onChangeButton} value={2}>
            2
          </Radio.Input>
          <Radio.Input onChange={onChangeButton} value={3}>
            3
          </Radio.Input>
        </Radio.Group>
        {buttonValue} was selected
      </div>
    </div>
  )
}
